mapper.select:
select id
from position_snapshot
where exchange_code = #{exchangeCode}
  and symbol = #{symbol}
  and case lower(side)
        when 'buy' then 'long'
        when 'sell' then 'short'
        else lower(side)
      end = lower(#{side})
order by created_at desc, id desc
limit 1

select id, trace_id as traceId, exchange_code as exchangeCode, symbol, side, mode, order_ref as orderRef, client_order_id as clientOrderId, action, order_type as orderType, position_side as positionSide, reduce_only as reduceOnly, td_mode as tdMode, leverage, limit_price as limitPrice, quantity_base as quantityBase, okx_enhanced_execution as okxEnhancedExecution, filled_quantity as filledQuantity, avg_fill_price as avgFillPrice, fee, fee_ccy as feeCcy, post_only as postOnly, as status, as executionStatus, order_status as orderStatus, created_at as createdAt, updated_at as updatedAt, filled_at as filledAt, raw_payload as rawPayload from exchange_order
= #{status}
and
order_status = #{orderStatus}
order by id desc

select id, trace_id as traceId, exchange_code as exchangeCode, symbol, side, mode, order_ref as orderRef, client_order_id as clientOrderId, action, order_type as orderType, position_side as positionSide, reduce_only as reduceOnly, td_mode as tdMode, leverage, limit_price as limitPrice, quantity_base as quantityBase, okx_enhanced_execution as okxEnhancedExecution, filled_quantity as filledQuantity, avg_fill_price as avgFillPrice, fee, fee_ccy as feeCcy, post_only as postOnly, as status, as executionStatus, order_status as orderStatus, created_at as createdAt, updated_at as updatedAt, filled_at as filledAt, raw_payload as rawPayload from exchange_order where in ('pending', 'submitted', 'partial')
and exchange_code = #{exchangeCode}
and symbol = #{symbol}
and mode = #{mode}
order by updated_at desc, created_at desc, id desc
